#ifndef HW_ARM_RK3588_IOMMU_H
#define HW_ARM_RK3588_IOMMU_H

#include "qemu/osdep.h"
#include "hw/core/sysbus.h"
#include "system/memory.h"

#define TYPE_RK3588_IOMMU "rk3588-iommu"
OBJECT_DECLARE_SIMPLE_TYPE(RkIommuState, RK3588_IOMMU);

RkIommuState *rk3588_create_iommu_window(uint64_t base, uint64_t size);

/* DMA is split at 4 KiB boundaries; on failure preceding pages may have
 * already transferred. No hardware fault IRQ is generated by this API yet. */
MemTxResult rk3588_iommu_dma_read(RkIommuState *s, uint32_t iova,
                                 void *buf, size_t len);
MemTxResult rk3588_iommu_dma_write(RkIommuState *s, uint32_t iova,
                                  const void *buf, size_t len);

#endif
